"""
app_import.py — change EXISTING applications with the studio.

  * Apps generated by this studio carry their design in `evoke-app.json` (project
    root). Re-opening one (project ZIP or the deployed CF app's package) restores
    requirement, blueprint, service and destination, so it can be refined and
    redeployed under the same name.
  * Client Fiori Elements apps (V2 or V4) are reverse-engineered into a blueprint
    (manifest + local annotations + service metadata) and enhanced IN PLACE: the
    studio writes an overlay annotation file (later local annotations override
    earlier ones) and merges a few safe manifest settings — their own code,
    extensions and files stay untouched.
  * Client freestyle apps are changed by the AI as reviewed file edits (diff).
"""

from __future__ import annotations

import base64
import difflib
import io
import json
import os
import re
import shutil
import subprocess
import tempfile
import xml.etree.ElementTree as ET
import zipfile
from typing import Callable, Dict, List, Optional, Tuple

DESIGN_FILE = "evoke-app.json"
OVERLAY = "annotations/evoke_overlay.xml"
TEXT_EXT = (".json", ".js", ".ts", ".xml", ".html", ".htm", ".properties", ".yaml", ".yml", ".css", ".less",
            ".md", ".txt", ".cds", ".mjs", ".cjs", ".env", ".gitignore", ".npmrc", ".editorconfig", ".mtaext")
SKIP_DIRS = ("node_modules/", "dist/", "mta_archives/", ".git/", "resources/")


class ImportError_(ValueError):
    pass


# ─────────────────────────────────────────────────────────────────────────────
# Reading projects
# ─────────────────────────────────────────────────────────────────────────────
def read_zip(data: bytes) -> Tuple[Dict[str, str], Dict[str, bytes]]:
    """ZIP -> (text files, binary files), paths relative to the project root
    (the folder that holds the webapp / manifest)."""
    try:
        zf = zipfile.ZipFile(io.BytesIO(data))
    except zipfile.BadZipFile as e:
        raise ImportError_(f"Not a ZIP archive: {e}")
    names = [n for n in zf.namelist() if not n.endswith("/")]
    manifests = sorted((n for n in names if n.endswith("manifest.json") and "node_modules/" not in n),
                       key=lambda n: n.count("/"))
    if not manifests:
        raise ImportError_("No manifest.json found — is this a SAPUI5 / Fiori project?")
    m = manifests[0]
    # project root = parent of webapp/ (or of the manifest when there is no webapp folder)
    parts = m.split("/")
    if len(parts) >= 2 and parts[-2] == "webapp":
        root = "/".join(parts[:-2])
    else:
        root = "/".join(parts[:-1])
    pre = (root + "/") if root else ""
    text, binary = {}, {}
    for n in names:
        if not n.startswith(pre):
            continue
        rel = n[len(pre):]
        if any(rel.startswith(d) or f"/{d}" in rel for d in SKIP_DIRS):
            continue
        raw = zf.read(n)
        if rel.lower().endswith(TEXT_EXT) or "." not in rel.split("/")[-1]:
            try:
                text[rel] = raw.decode("utf-8")
                continue
            except UnicodeDecodeError:
                pass
        binary[rel] = raw
    return text, binary


def to_zip(text: Dict[str, str], binary: Dict[str, bytes]) -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for p, c in sorted(text.items()):
            zf.writestr(p, c)
        for p, c in sorted(binary.items()):
            zf.writestr(p, c)
    return buf.getvalue()


def webapp_prefix(files: Dict[str, str]) -> str:
    return "webapp/" if "webapp/manifest.json" in files else ""


# ─────────────────────────────────────────────────────────────────────────────
# Deployed apps on Cloud Foundry (package download via the CF API)
# ─────────────────────────────────────────────────────────────────────────────
def _cf() -> str:
    return shutil.which("cf") or shutil.which("cf8") or os.path.join("bin", "cf")


def _cf_run(args: List[str], timeout: int = 90, cf_home: Optional[str] = None) -> str:
    from deployer import _cf_env, _resolve_cmd
    r = subprocess.run(_resolve_cmd(["cf"] + args), capture_output=True, text=True, timeout=timeout,
                       env=_cf_env(cf_home), stdin=subprocess.DEVNULL)
    if r.returncode != 0:
        raise ImportError_((r.stderr or r.stdout).strip()[-300:] or "cf command failed")
    return r.stdout


def list_cf_apps(cf_home: Optional[str] = None) -> List[Dict]:
    """Apps in the targeted space: [{name, state, generated}] (generated = has the studio's
    approuter layout — confirmed only on download)."""
    out = _cf_run(["apps"], cf_home=cf_home)
    apps = []
    started = False
    for line in out.splitlines():
        if line.startswith("name "):
            started = True
            continue
        if started and line.strip():
            cols = line.split()
            apps.append({"name": cols[0], "state": cols[1] if len(cols) > 1 else ""})
    return apps


def cf_api(path: str, cf_home: Optional[str] = None) -> Dict:
    """GET on the CF v3 API with the session in cf_home."""
    import requests
    token = _cf_run(["oauth-token"], cf_home=cf_home).strip().splitlines()[-1]
    api = ""
    for line in _cf_run(["api"], cf_home=cf_home).splitlines():
        m = re.search(r"(https://\S+)", line)
        if m:
            api = m.group(1).rstrip("/")
            break
    r = requests.get(api + path, headers={"Authorization": token}, timeout=60)
    r.raise_for_status()
    return r.json()


def cf_app_info(name: str, cf_home: Optional[str] = None) -> Dict:
    """Routes, approuter destinations (name + URL only — never credentials), bound service names and the
    names of user-provided environment variables of a deployed app."""
    guid = _cf_run(["app", name, "--guid"], cf_home=cf_home).strip()
    env = cf_api(f"/v3/apps/{guid}/env", cf_home)
    ev = env.get("environment_variables") or {}
    dests = []
    try:
        for d in json.loads(ev.get("destinations") or "[]"):
            if d.get("name") and d.get("url"):
                dests.append({"name": d["name"], "url": d["url"]})
    except ValueError:
        pass
    vcap = ((env.get("system_env_json") or {}).get("VCAP_SERVICES")) or {}
    services = [{"label": label, "name": s.get("name", "")} for label, items in vcap.items() for s in items]
    routes = ["https://" + r["url"] for r in cf_api(f"/v3/apps/{guid}/routes", cf_home).get("resources", []) if r.get("url")]
    return {"name": name, "guid": guid, "routes": routes, "destinations": dests, "services": services,
            "env_names": sorted(k for k in ev if k not in ("destinations", "DEPLOY_ATTRIBUTES"))}


def cf_app_for_url(url: str, cf_home: Optional[str] = None) -> str:
    """Name of the app in the targeted org that serves `url` ('' when none / not visible)."""
    from urllib.parse import urlparse
    host = (urlparse(url).hostname or "")
    if not host or "." not in host:
        return ""
    sub, domain = host.split(".", 1)
    try:
        routes = cf_api(f"/v3/routes?hosts={sub}&per_page=20", cf_home).get("resources", [])
        for r in routes:
            if (r.get("url") or "").split("/")[0] != host:
                continue
            for d in r.get("destinations") or []:
                guid = (d.get("app") or {}).get("guid")
                if guid:
                    return cf_api(f"/v3/apps/{guid}", cf_home).get("name", "")
    except Exception:  # noqa: BLE001 — another org / no permission: treated as external
        return ""
    return ""


def download_cf_app(name: str, cf_home: Optional[str] = None) -> bytes:
    """ZIP of the source package of a deployed CF app (what `cf push` / MTA uploaded)."""
    import requests
    guid = _cf_run(["app", name, "--guid"], cf_home=cf_home).strip()
    token = _cf_run(["oauth-token"], cf_home=cf_home).strip().splitlines()[-1]
    api = ""
    for line in _cf_run(["api"], cf_home=cf_home).splitlines():
        m = re.search(r"(https://\S+)", line)
        if m:
            api = m.group(1).rstrip("/")
            break
    if not (guid and token and api):
        raise ImportError_("Could not resolve the app on Cloud Foundry (cf login / target?).")
    h = {"Authorization": token}
    r = requests.get(f"{api}/v3/apps/{guid}/packages", headers=h, timeout=60,
                     params={"order_by": "-created_at", "per_page": 5})
    r.raise_for_status()
    pkgs = [p for p in r.json().get("resources", []) if p.get("type") == "bits" and p.get("state") == "READY"]
    if not pkgs:
        raise ImportError_(f"No source package available for '{name}' (docker or expired package).")
    d = requests.get(f"{api}/v3/packages/{pkgs[0]['guid']}/download", headers=h, timeout=300,
                     allow_redirects=True)
    d.raise_for_status()
    return d.content


# ─────────────────────────────────────────────────────────────────────────────
# Detecting what was imported
# ─────────────────────────────────────────────────────────────────────────────
def analyze(files: Dict[str, str]) -> Dict:
    """{kind: generated | fe_v4 | fe_v2 | ovp | freestyle, app_id, title, service_path,
    odata_version, metadata, main_entity, design, notes}"""
    wp = webapp_prefix(files)
    try:
        man = json.loads(files[wp + "manifest.json"])
    except (KeyError, ValueError) as e:
        raise ImportError_(f"manifest.json unreadable: {e}")
    app = man.get("sap.app", {})
    ds = app.get("dataSources", {}) or {}
    main_ds = ds.get("mainService") or next((v for v in ds.values() if v.get("type", "OData") == "OData"), {})
    libs = ((man.get("sap.ui5") or {}).get("dependencies") or {}).get("libs") or {}
    out = {"app_id": app.get("id", ""), "title": app.get("title", ""), "manifest": man,
           "service_path": main_ds.get("uri", ""),
           "odata_version": (main_ds.get("settings") or {}).get("odataVersion", "2.0"),
           "metadata": "", "main_entity": "", "design": None, "notes": [], "webapp": wp}
    local_uri = (main_ds.get("settings") or {}).get("localUri") or "localService/metadata.xml"
    for cand in (wp + local_uri, wp + "localService/metadata.xml", wp + "localService/mainService/metadata.xml"):
        if cand in files:
            out["metadata"] = files[cand]
            break
    dfile = DESIGN_FILE if DESIGN_FILE in files else (wp + DESIGN_FILE if wp + DESIGN_FILE in files else None)
    if dfile:
        try:
            out["design"] = json.loads(files[dfile])
            out["kind"] = "generated"
            # further services of a multi-service app: their metadata travels in localService/<alias>/
            out["extra_services"] = []
            for s in out["design"].get("services") or []:
                md = files.get(wp + s.get("metadata", "")) or ""
                if md:
                    out["extra_services"].append({"service_url": s.get("service_url", ""), "edmx": md,
                                                  "title": s.get("title", ""),
                                                  "sets": md.count("<EntitySet ")})
                else:
                    out["notes"].append(f"Metadata of {s.get('service_url')} is missing in the project — "
                                        f"add that service again in step 1.")
            return out
        except ValueError:
            out["notes"].append(f"{DESIGN_FILE} is not valid JSON — treated as a client app.")
    if "sap.ovp" in man:
        out["kind"] = "ovp"
    elif "sap.fe.templates" in libs or any("sap.fe.templates" in json.dumps(t)
                                           for t in ((man.get("sap.ui5") or {}).get("routing") or {}).get("targets", {}).values()):
        out["kind"] = "fe_v4"
        tg = ((man.get("sap.ui5") or {}).get("routing") or {}).get("targets", {})
        for t in tg.values():
            st = ((t.get("options") or {}).get("settings") or {})
            if "ListReport" in str(t.get("name", "")) or not out["main_entity"]:
                cp = st.get("contextPath") or ("/" + st["entitySet"] if st.get("entitySet") else "")
                if cp:
                    out["main_entity"] = cp.strip("/").split("/")[0]
    elif "sap.ui.generic.app" in man:
        out["kind"] = "fe_v2"
        pages = (man["sap.ui.generic.app"].get("pages") or {})
        first = pages[next(iter(pages))] if isinstance(pages, dict) and pages else (pages[0] if pages else {})
        out["main_entity"] = first.get("entitySet", "")
    else:
        out["kind"] = "freestyle"
    if not out["metadata"] and out["kind"] != "freestyle":
        out["notes"].append("The project has no local metadata.xml — load the service in step 1 so the "
                            "studio knows its entity sets and fields.")
    return out


# ─────────────────────────────────────────────────────────────────────────────
# Generated apps: restore the stored design
# ─────────────────────────────────────────────────────────────────────────────
def design_record(*, requirement: str, blueprint: Dict, spec: Optional[Dict], coverage: Optional[List],
                  app_id: str, service_url: str, destination: str, use_existing_destination: bool,
                  on_premise: bool, auth_type: str, theme: str, services: Optional[List[Dict]] = None) -> str:
    import time
    bp = dict(blueprint)
    return json.dumps({
        "generator": "Evoke Fiori App Studio", "format": 1, "saved_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "app_id": app_id, "requirement": requirement, "service_url": service_url,
        "destination": destination, "use_existing_destination": use_existing_destination,
        "on_premise": on_premise, "auth_type": auth_type, "theme": theme,
        "blueprint": bp, "spec": spec, "coverage": coverage or [],
        # further OData services of a multi-service app (metadata travels in the project)
        "services": services or [],
    }, indent=1, ensure_ascii=False)


# ─────────────────────────────────────────────────────────────────────────────
# Client Fiori Elements apps: reverse-engineer a blueprint
# ─────────────────────────────────────────────────────────────────────────────
def _annotation_files(files: Dict[str, str], info: Dict) -> List[str]:
    wp = info["webapp"]
    ds = (info["manifest"].get("sap.app") or {}).get("dataSources") or {}
    out = []
    for v in ds.values():
        if v.get("type") == "ODataAnnotation":
            uri = (v.get("settings") or {}).get("localUri") or v.get("uri", "")
            if wp + uri in files:
                out.append(wp + uri)
    return out


def _collect(root) -> Dict[str, Dict]:
    """Per-target UI annotations of an annotation/metadata document."""
    def loc(t):
        return t.split("}")[-1]
    res: Dict[str, Dict] = {}
    for anns in root.iter():
        if loc(anns.tag) != "Annotations":
            continue
        tgt = anns.attrib.get("Target", "")
        b = res.setdefault(tgt.split("/")[0].split(".")[-1], {"line_item": [], "selection": [], "groups": {},
                                                                "facets": [], "title": ""})
        for a in anns:
            if loc(a.tag) != "Annotation":
                continue
            term, q = a.attrib.get("Term", ""), a.attrib.get("Qualifier", "")
            paths = [e.attrib.get("Path") for e in a.iter() if loc(e.tag) == "PropertyValue"
                     and e.attrib.get("Property") == "Value" and e.attrib.get("Path")]
            if term.endswith("UI.LineItem") and not q:
                b["line_item"] = paths
            elif term.endswith("UI.SelectionFields"):
                b["selection"] = [e.text.strip() for e in a.iter() if loc(e.tag) == "PropertyPath" and e.text]
            elif term.endswith("UI.FieldGroup"):
                b["groups"][q or "General"] = paths
            elif term.endswith("UI.HeaderInfo"):
                b["title"] = next((e.attrib.get("Path") for e in a.iter() if loc(e.tag) == "PropertyValue"
                                   and e.attrib.get("Path")), "")
            elif term.endswith("UI.Facets"):
                for rec in a.iter():
                    if loc(rec.tag) != "Record":
                        continue
                    label = next((e.attrib.get("String") for e in rec if e.attrib.get("Property") == "Label"), "")
                    target = next((e.attrib.get("AnnotationPath") for e in rec if e.attrib.get("Property") == "Target"), "")
                    if target:
                        b["facets"].append({"label": label or "", "target": target})
    return res


def blueprint_from_fe(files: Dict[str, str], info: Dict, model: Dict) -> Tuple[Dict, List[str]]:
    """A design blueprint that reproduces the client FE app (the starting point for
    enhancements). Unknown parts fall back to the rule-based defaults."""
    import blueprint as bpm
    notes = []
    sets = {e["name"]: e for e in model["entity_sets"]}
    es = sets.get(info["main_entity"]) or bpm._pick_main(info.get("title", ""), model)
    if info["main_entity"] and info["main_entity"] not in sets:
        notes.append(f"Main entity '{info['main_entity']}' not in the metadata — using {es['name']}.")
    ann: Dict[str, Dict] = {}
    docs = [info["metadata"]] + [files[p] for p in _annotation_files(files, info)]
    for doc in docs:
        try:
            got = _collect(ET.fromstring(doc.encode("utf-8")))
        except ET.ParseError:
            continue
        for k, v in got.items():                      # later documents override earlier ones
            cur = ann.setdefault(k, {"line_item": [], "selection": [], "groups": {}, "facets": [], "title": ""})
            for key in ("line_item", "selection", "title"):
                if v[key]:
                    cur[key] = v[key]
            cur["groups"].update(v["groups"])
            if v["facets"]:
                cur["facets"] = v["facets"]
    a = ann.get(es["entity_type"], {})
    i18n = {}
    for line in files.get(info["webapp"] + "i18n/i18n.properties", "").splitlines():
        if "=" in line and not line.lstrip().startswith("#"):
            k, v = line.split("=", 1)
            i18n[k.strip()] = v.strip()

    def text(label, fallback):
        m = re.match(r"^\{@?i18n>([^}]+)\}$", label or "")
        if m:
            return i18n.get(m.group(1)) or fallback
        return label or fallback
    sections, tables = [], []
    for f in a.get("facets") or []:
        t = f["target"]
        if "@UI.FieldGroup" in t or "@com.sap.vocabularies.UI.v1.FieldGroup" in t:
            q = t.split("#")[-1] if "#" in t else "General"
            flds = a["groups"].get(q) or []
            if flds:
                sections.append({"title": text(f["label"], q), "fields": flds})
        elif "/@" in t and "LineItem" in t:
            tables.append({"navigation": t.split("/@")[0], "title": text(f["label"], "")})
    if not sections and a.get("groups"):
        sections = [{"title": q, "fields": v} for q, v in a["groups"].items() if v]
    floorplan = "ListReportObjectPage"
    if info["kind"] == "fe_v2" and "AnalyticalListPage" in json.dumps(info["manifest"].get("sap.ui.generic.app", {})):
        floorplan = "AnalyticalListPage"
    raw = {"app": {"title": _plain_title(files, info) or es.get("label") or es["name"]},
           "floorplan": floorplan,
           "main": {"entity_set": es["name"], "title_field": a.get("title") or "",
                    "columns": [{"field": f} for f in a.get("line_item") or []],
                    "filters": [{"field": f} for f in a.get("selection") or []]},
           "object_page": {"sections": sections, "tables": tables},
           "reasoning": "Reconstructed from the existing application's manifest and annotations."}
    return raw, notes


def _plain_title(files: Dict[str, str], info: Dict) -> str:
    t = info.get("title") or ""
    m = re.match(r"^\{\{(.+)\}\}$", t)
    if not m:
        return t
    props = files.get(info["webapp"] + "i18n/i18n.properties", "")
    for line in props.splitlines():
        if line.split("=", 1)[0].strip() == m.group(1):
            return line.split("=", 1)[1].strip()
    return ""


def fe_overlay(files: Dict[str, str], info: Dict, generated: Dict[str, str]) -> Tuple[Dict[str, str], List[str]]:
    """Enhance a client FE app in place: the studio's annotations for the (enhanced)
    blueprint become an overlay annotation file registered LAST (so it wins), new
    i18n texts are appended, and safe manifest settings are merged."""
    wp = info["webapp"]
    out = dict(files)
    notes = []
    gen_ann = generated.get("annotations/annotations.xml") or generated.get("webapp/annotations/annotations.xml", "")
    # OData V4: "A schema cannot span more than one document" — the overlay needs its own
    # schema namespace (the app's own local annotation file usually uses "local").
    gen_ann = re.sub(r'(<Schema[^>]*\sNamespace=")[^"]*(")', r"\1evoke.overlay\2", gen_ann, count=1)
    out[wp + OVERLAY] = gen_ann
    man = json.loads(files[wp + "manifest.json"])
    gman = json.loads(generated["manifest.json"])
    ds = man.setdefault("sap.app", {}).setdefault("dataSources", {})
    ds["evokeOverlay"] = {"type": "ODataAnnotation", "uri": OVERLAY, "settings": {"localUri": OVERLAY}}
    main_key = next((k for k, v in ds.items() if v.get("type", "OData") == "OData" and k != "evokeOverlay"), None)
    if main_key:
        anns = ds[main_key].setdefault("settings", {}).setdefault("annotations", [])
        if "evokeOverlay" in anns:
            anns.remove("evokeOverlay")
        anns.append("evokeOverlay")
    # i18n: append texts the overlay references
    i18n_path = wp + "i18n/i18n.properties"
    existing = out.get(i18n_path, "")
    have = {l.split("=", 1)[0].strip() for l in existing.splitlines() if "=" in l}
    new = [l for l in (generated.get("i18n/i18n.properties") or "").splitlines()
           if "=" in l and l.split("=", 1)[0].strip() not in have]
    if new:
        out[i18n_path] = existing.rstrip("\n") + "\n\n# --- added by Evoke Fiori App Studio ---\n" + "\n".join(new) + "\n"
    # manifest: table views, personalization (V4) / quick variants (V2) — merged, nothing removed
    if info["kind"] == "fe_v4":
        g_targets = ((gman.get("sap.ui5") or {}).get("routing") or {}).get("targets", {})
        g_lr = ((g_targets.get("ListReport") or {}).get("options") or {}).get("settings") or {}
        for t in ((man.get("sap.ui5") or {}).get("routing") or {}).get("targets", {}).values():
            if "ListReport" in str(t.get("name", "")):
                st = t.setdefault("options", {}).setdefault("settings", {})
                if g_lr.get("views"):
                    st["views"] = g_lr["views"]
                cc = st.setdefault("controlConfiguration", {}).setdefault("@com.sap.vocabularies.UI.v1.LineItem", {})
                ts = cc.setdefault("tableSettings", {})
                for k, v in (((g_lr.get("controlConfiguration") or {}).get("@com.sap.vocabularies.UI.v1.LineItem") or {})
                             .get("tableSettings") or {}).items():
                    ts.setdefault(k, v)
        libs = man.setdefault("sap.ui5", {}).setdefault("dependencies", {}).setdefault("libs", {})
        for lib, v in (((gman.get("sap.ui5") or {}).get("dependencies") or {}).get("libs") or {}).items():
            if lib == "sap.suite.ui.microchart":
                libs.setdefault(lib, v)
        notes.append("Layout (flexible columns) is left as the app has it — the studio does not restructure an "
                     "existing app's routing.")
    elif info["kind"] == "fe_v2":
        g_pages = (gman.get("sap.ui.generic.app") or {}).get("pages") or {}
        g_lr = next(iter(g_pages.values()), {}).get("component", {}).get("settings", {}) if g_pages else {}
        pages = (man.get("sap.ui.generic.app") or {}).get("pages") or {}
        lr = next(iter(pages.values()), None) if isinstance(pages, dict) else (pages[0] if pages else None)
        if lr is not None and g_lr.get("quickVariantSelectionX"):
            lr.setdefault("component", {}).setdefault("settings", {})["quickVariantSelectionX"] = g_lr["quickVariantSelectionX"]
    out[wp + "manifest.json"] = json.dumps(man, indent=4, ensure_ascii=False)
    return out, notes


# ─────────────────────────────────────────────────────────────────────────────
# Client freestyle apps: AI code changes, reviewed as a diff
# ─────────────────────────────────────────────────────────────────────────────
CODE_SYSTEM = (
    "You are a senior SAPUI5 developer. You change an existing SAPUI5 freestyle application exactly as "
    "requested, following its existing structure, naming and coding style (sap.ui.define modules, XML "
    "views, i18n texts in i18n.properties, no inline texts). Do not rewrite unrelated code. Only use "
    "controls that exist in SAPUI5 1.120+. For i18n .properties files return ONLY the new key=value "
    "lines (never change existing texts). Reply with STRICT minified JSON only: "
    '{"files": {"<relative path>": "<COMPLETE new file content>"}, "summary": "<what you changed>"} '
    "— include only files you change or add."
)


def _code_context(files: Dict[str, str], budget: int = 150_000) -> str:
    wp = webapp_prefix(files)
    order = [p for p in files if p.startswith(wp) and p.endswith((".json", ".xml", ".js", ".properties", ".html"))
             and not p.startswith(wp + "localService") and "/test/" not in p and not p.endswith(".min.js")]
    order.sort(key=lambda p: (not p.endswith("manifest.json"), "view" not in p, "controller" not in p, p))
    out, used = [], 0
    for p in order:
        c = files[p]
        if used + len(c) > budget:
            out.append(f"=== {p} (omitted: {len(c)} chars) ===")
            continue
        out.append(f"=== {p} ===\n{c}")
        used += len(c)
    return "\n".join(out)


def ai_code_change(files: Dict[str, str], instruction: str, ai_fn: Callable, metadata_ctx: str = "") -> Dict:
    """{files: {path: new content}, summary, diff: str}"""
    import ai_designer
    user = (f"CHANGE REQUEST:\n{instruction.strip()}\n\n"
            + (f"ODATA SERVICE:\n{metadata_ctx[:30000]}\n\n" if metadata_ctx else "")
            + f"PROJECT FILES:\n{_code_context(files)}")
    res = ai_designer.ask_json(ai_fn, CODE_SYSTEM, user)
    changes = {p: c for p, c in (res.get("files") or {}).items()
               if isinstance(c, str) and not p.startswith(("/", "..")) and ".." not in p}
    # Text bundles: existing texts are never changed — only new keys are appended.
    for p in list(changes):
        if p.endswith(".properties") and p in files:
            merged = _merge_properties(files[p], changes[p])
            if merged == files[p]:
                changes.pop(p)
            else:
                changes[p] = merged
    return {"files": changes, "summary": str(res.get("summary") or ""), "diff": diff(files, changes)}


def _merge_properties(old: str, new: str) -> str:
    have = {l.split("=", 1)[0].strip() for l in old.splitlines() if "=" in l and not l.lstrip().startswith("#")}
    add = [l for l in new.splitlines() if "=" in l and not l.lstrip().startswith("#")
           and l.split("=", 1)[0].strip() not in have]
    if not add:
        return old
    return old.rstrip("\n") + "\n\n# --- added by Evoke Fiori App Studio ---\n" + "\n".join(add) + "\n"


def diff(old: Dict[str, str], changes: Dict[str, str]) -> str:
    out = []
    for p, new in sorted(changes.items()):
        a = (old.get(p) or "").splitlines(keepends=True)
        b = new.splitlines(keepends=True)
        out += difflib.unified_diff(a, b, fromfile=f"a/{p}", tofile=f"b/{p}", n=2)
    return "".join(out)


def check_files(changes: Dict[str, str]) -> List[str]:
    """Syntax check of changed files (XML/JSON always, JS with node when available)."""
    errs = []
    for p, c in changes.items():
        if p.endswith(".xml"):
            try:
                ET.fromstring(c.encode("utf-8"))
            except ET.ParseError as e:
                errs.append(f"{p}: XML error {e}")
        elif p.endswith(".json"):
            try:
                json.loads(c)
            except ValueError as e:
                errs.append(f"{p}: JSON error {e}")
        elif p.endswith(".js") and shutil.which("node"):
            with tempfile.NamedTemporaryFile("w", suffix=".js", delete=False, encoding="utf-8") as f:
                f.write(c)
            r = subprocess.run(["node", "--check", f.name], capture_output=True, text=True)
            os.unlink(f.name)
            if r.returncode:
                errs.append(f"{p}: {r.stderr.strip().splitlines()[-1] if r.stderr else 'syntax error'}")
    return errs
